public import Foundation

/// Typed decoder for a `terminal.render_grid` push-event payload that nests the
/// frame under a `render_grid` key.
///
/// Some hosts wrap the frame (`{"render_grid": { ... }}`) and some emit the bare
/// frame as the whole payload. This DTO decodes the wrapped form; the caller
/// falls back to decoding the payload directly as a
/// ``MobileTerminalRenderGridFrame`` when ``frame`` is `nil`.
public struct MobileTerminalRenderGridEvent: Decodable, Sendable {
    /// The nested render-grid frame, if the payload used the wrapped form.
    public let frame: MobileTerminalRenderGridFrame?

    private enum CodingKeys: String, CodingKey {
        case frame = "render_grid"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        frame = try container.decodeIfPresent(MobileTerminalRenderGridFrame.self, forKey: .frame)
    }

    /// Decode a wrapped render-grid event from a raw JSON payload.
    /// - Parameter data: The event payload JSON.
    /// - Returns: The decoded event.
    /// - Throws: A decoding error if the payload is not a JSON object.
    public static func decode(_ data: Data) throws -> MobileTerminalRenderGridEvent {
        try JSONDecoder().decode(Self.self, from: data)
    }
}

public import Foundation

/// Typed decoder for the `mobile.events.subscribe` RPC result.
///
/// The Mac acknowledges a subscription by echoing back the `stream_id` it
/// registered. A non-empty `stream_id` is the success signal the listener loop
/// keys off; an absent or empty value means the subscription did not take.
public struct MobileEventSubscribeResponse: Decodable, Sendable {
    /// The server-registered event stream identifier.
    ///
    /// Empty or missing when the subscription was not accepted.
    public let streamID: String

    /// Whether the host already had a registration for this `stream_id` on
    /// this connection before processing the request (`mobile.events.subscribe`
    /// is idempotent per stream id).
    ///
    /// `false` means this acknowledgement INSTALLED the registration, so any
    /// events emitted while it was absent were never delivered; the liveness
    /// probe uses that to trigger a catch-up replay. `nil` when the host
    /// predates the field, which callers must treat as "unknown, assume it was
    /// already active" so older Macs keep today's behavior.
    public let alreadySubscribed: Bool?

    /// The selected event delivery path, absent on older hosts.
    public let eventTransport: String?

    private enum CodingKeys: String, CodingKey {
        case streamID = "stream_id"
        case alreadySubscribed = "already_subscribed"
        case eventTransport = "event_transport"
    }

    /// Decode a subscribe acknowledgement from raw JSON data.
    ///
    /// Tolerant of a missing `stream_id` (decodes to an empty string) so a
    /// malformed acknowledgement is treated as "not subscribed" rather than a
    /// thrown error the caller would have to special-case.
    /// - Parameter data: The RPC result payload.
    /// - Returns: The decoded acknowledgement.
    /// - Throws: A decoding error only if the payload is not a JSON object.
    public static func decode(_ data: Data) throws -> MobileEventSubscribeResponse {
        try JSONDecoder().decode(Self.self, from: data)
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        streamID = (try container.decodeIfPresent(String.self, forKey: .streamID)) ?? ""
        alreadySubscribed = try container.decodeIfPresent(Bool.self, forKey: .alreadySubscribed)
        eventTransport = try container.decodeIfPresent(String.self, forKey: .eventTransport)
    }
}

public import CMUXMobileCore
public import Foundation

/// Runtime configuration the RPC layer needs, supplied by the app's DI bundle.
///
/// Keeping this as a protocol lets ``MobileCoreRPCClient`` depend only on
/// `CMUXMobileCore` while the app's `CMUXMobileRuntime` conforms to it at the
/// composition root. This avoids pulling the auth domain into the service layer.
public protocol MobileSyncRuntime: Sendable {
    /// Factory that builds a byte transport for a given attach route.
    var transportFactory: any CmxByteTransportFactory { get }
    /// Mints a Stack Auth access token for requests not covered by an attach ticket.
    var stackAccessTokenProvider: @Sendable () async throws -> String { get }
    /// Returns a cached Stack Auth access token for best-effort status probes.
    /// Must not refresh, cancel, or otherwise mutate auth state.
    var stackAccessTokenForStatusProvider: @Sendable () async -> String? { get }
    /// Force-mints a fresh Stack Auth access token, bypassing any cached-token
    /// freshness check. The connection layer calls this exactly once after the
    /// host rejects a request on auth grounds, so the retry presents a genuinely
    /// new credential instead of re-sending the rejected (likely stale) token.
    var stackAccessTokenForceRefresher: @Sendable () async throws -> String { get }
    /// Per-request timeout deadline, in nanoseconds.
    var rpcRequestTimeoutNanoseconds: UInt64 { get }
    /// Clock used to compare attach-ticket expiry, injected for testability.
    var now: @Sendable () -> Date { get }
    /// Transport kinds the app can dial, used to filter attach routes before
    /// connecting. Empty means "no filter" (accept every advertised route).
    var supportedRouteKinds: [CmxAttachTransportKind] { get }
    /// Shorter deadline for pairing-time requests (ticket mint, initial
    /// workspace list), in nanoseconds.
    var pairingRequestTimeoutNanoseconds: UInt64 { get }
    /// Hard deadline for one user-initiated pairing attempt, in nanoseconds.
    /// This bounds the whole QR/manual flow, not just one route or RPC.
    var pairingAttemptTimeoutNanoseconds: UInt64 { get }
    /// Whether the host supports server-pushed events. When `false`, the shell
    /// skips background subscribe/poll so scripted-transport tests do not
    /// consume responses intended for foreground methods.
    var supportsServerPushEvents: Bool { get }
    /// Optional Iroh-only source for independently framed server events.
    /// A nil provider preserves control-stream delivery for every route.
    var independentEventByteStreamProvider: CmxIndependentEventByteStreamProvider? { get }
    /// Optional source for one independent, sequence-aware terminal lane per
    /// mounted surface. A nil provider preserves control/event delivery.
    var terminalLaneProvider: MobileTerminalLaneProvider? { get }
    /// Optional source for low-priority raw artifact bytes on an admitted Iroh peer.
    var artifactLaneProvider: MobileArtifactLaneProvider? { get }
    /// Optional source for one dedicated simulator-stream v2 video lane per
    /// Mac simulator panel. A nil provider keeps phones on the v1 event stream.
    var simulatorStreamLaneProvider: MobileSimulatorStreamLaneProvider? { get }
    /// Bounded deadline, in nanoseconds, for the render-grid liveness
    /// watchdog's subscription probe (an idempotent `mobile.events.subscribe`
    /// re-assert). A healthy idle terminal legitimately pushes no events, so
    /// the watchdog verifies prolonged silence with this probe before
    /// declaring the stream dead; the deadline bounds how long a dead
    /// transport can stall that verdict.
    var livenessProbeTimeoutNanoseconds: UInt64 { get }

    /// Hard ceiling on one automatic reconnect attempt (stored-Mac redial)
    /// end to end. An Iroh dial can hang far past any per-transport connect
    /// timeout (relay DNS churn, hole-punch stalls), and an unbounded attempt
    /// wedges the recovery owner: no failure is ever recorded, no backoff
    /// retry is ever scheduled, and every other trigger defers to the
    /// "in-flight" attempt forever. At the deadline the attempt is abandoned
    /// and settled as timed out so the automatic backoff retry loop keeps
    /// running.
    var reconnectAttemptDeadlineNanoseconds: UInt64 { get }
}

public extension MobileSyncRuntime {
    var independentEventByteStreamProvider: CmxIndependentEventByteStreamProvider? { nil }
    var terminalLaneProvider: MobileTerminalLaneProvider? { nil }
    var artifactLaneProvider: MobileArtifactLaneProvider? { nil }
    var simulatorStreamLaneProvider: MobileSimulatorStreamLaneProvider? { nil }

    /// Returns a cached Stack access token for best-effort status probes.
    var stackAccessTokenForStatusProvider: @Sendable () async -> String? {
        { nil }
    }

    /// Default user-facing pairing deadline. Individual RPCs can have their own
    /// request timeout, but the sheet must not spin through stacked route waits.
    var pairingAttemptTimeoutNanoseconds: UInt64 { 8_000_000_000 }

    /// Default probe deadline: generous against a momentarily loaded Mac,
    /// while keeping dead-stream recovery within a few seconds of the silence
    /// threshold instead of the full ``rpcRequestTimeoutNanoseconds``.
    var livenessProbeTimeoutNanoseconds: UInt64 { 3_000_000_000 }

    /// Default reconnect-attempt ceiling: comfortably above a slow relay dial
    /// (transport connects bound themselves near 15s) while turning a hung
    /// dial into a settled, retryable failure within half a minute.
    var reconnectAttemptDeadlineNanoseconds: UInt64 { 30_000_000_000 }
}

import Foundation

/// The address shape used to reach an attach route.
public enum CmxAttachEndpoint: Equatable, Sendable {
    /// The maximum number of reachability hints accepted for one Iroh peer.
    public static let maximumIrohPathHintCount = 16

    /// A direct host and TCP port.
    case hostPort(host: String, port: Int)
    /// An authenticated Iroh identity plus untrusted reachability hints.
    case peer(identity: CmxIrohPeerIdentity, pathHints: [CmxIrohPathHint])
    /// A URL-based transport endpoint.
    case url(String)
}

extension CmxAttachEndpoint: Codable {
    private enum CodingKeys: String, CodingKey {
        case type
        case host
        case port
        case id
        case relayHint = "relay_hint"
        case directAddrs = "direct_addrs"
        case relayURL = "relay_url"
        case pathHints = "path_hints"
        case url
    }

    private enum EndpointType: String, Codable {
        case hostPort = "host_port"
        case peer
        case url
    }

    /// Decodes and validates an attach endpoint.
    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let type = try container.decode(EndpointType.self, forKey: .type)
        switch type {
        case .hostPort:
            self = try .hostPort(
                host: container.decode(String.self, forKey: .host),
                port: container.decode(Int.self, forKey: .port)
            )
        case .peer:
            let identity = try CmxIrohPeerIdentity(
                endpointID: try container.decode(String.self, forKey: .id)
            )
            if let pathHints = try container.decodeIfPresent(
                [CmxIrohPathHint].self,
                forKey: .pathHints
            ) {
                self = .peer(identity: identity, pathHints: pathHints)
            } else {
                self = try .peer(
                    id: identity.endpointID,
                    relayHint: try container.decodeIfPresent(String.self, forKey: .relayHint),
                    directAddrs: try container.decodeIfPresent(
                        [String].self,
                        forKey: .directAddrs
                    ) ?? [],
                    relayURL: try container.decodeIfPresent(String.self, forKey: .relayURL)
                )
            }
        case .url:
            self = try .url(container.decode(String.self, forKey: .url))
        }
    }

    /// Encodes the endpoint while omitting unsafe legacy Iroh hint forms.
    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case let .hostPort(host, port):
            try container.encode(EndpointType.hostPort, forKey: .type)
            try container.encode(host, forKey: .host)
            try container.encode(port, forKey: .port)
        case let .peer(identity, pathHints):
            try container.encode(EndpointType.peer, forKey: .type)
            try container.encode(identity.endpointID, forKey: .id)
            // Encoding is deterministic: wall-clock freshness is applied by
            // the caller's disclosure/persistence boundary. Structurally
            // unsafe inert legacy values are never re-emitted.
            let wireSafePathHints = pathHints.filter(\.isSafeForCurrentWireFormat)
            if !wireSafePathHints.isEmpty {
                try container.encode(wireSafePathHints, forKey: .pathHints)
            }

            // Legacy fields cannot represent observation or expiry metadata.
            // Downgrade only timeless safe hints, otherwise an expired/future
            // path would be promoted indefinitely for an older consumer.
            let legacySafePathHints = wireSafePathHints.filter {
                $0.observedAt == nil && $0.expiresAt == nil
            }
            let relayHint = legacySafePathHints.first {
                $0.kind == .relayIdentifier
            }?.value
            // Legacy `direct_addrs` cannot carry expiry, privacy, or network
            // profile. Emitting private fallbacks there would silently promote
            // them for old clients, so only public primary addresses downgrade.
            let directAddrs = legacySafePathHints
                .filter { $0.kind == .directAddress && $0.use == .primary }
                .map(\.value)
            let relayURL = legacySafePathHints.first {
                $0.kind == .relayURL
            }?.value
            try container.encodeIfPresent(relayHint, forKey: .relayHint)
            if !directAddrs.isEmpty {
                try container.encode(directAddrs, forKey: .directAddrs)
            }
            try container.encodeIfPresent(relayURL, forKey: .relayURL)
        case let .url(url):
            try container.encode(EndpointType.url, forKey: .type)
            try container.encode(url, forKey: .url)
        }
    }
}

/// Validation failures for attach-route endpoints.
public enum CmxAttachRouteError: Error, Equatable, Sendable {
    /// A host/port route has an empty host.
    case emptyHost
    /// An Iroh peer route has an empty peer identity.
    case emptyPeerID
    /// An Iroh direct-address hint is empty.
    case emptyPeerAddress
    /// A URL or relay hint is empty.
    case emptyURL
    /// A host/port route uses a port outside the valid TCP range.
    case invalidPort(Int)
    /// A peer route exceeded ``CmxAttachEndpoint/maximumIrohPathHintCount``.
    case tooManyPeerPathHints(actual: Int, maximum: Int)
    /// The endpoint shape does not match its declared transport kind.
    case endpointMismatch(kind: CmxAttachTransportKind, endpoint: CmxAttachEndpoint)
}

public struct CmxAttachRoute: Codable, Equatable, Sendable {
    private enum CodingKeys: String, CodingKey {
        case id
        case kind
        case endpoint
        case priority
    }

    public let id: String
    public let kind: CmxAttachTransportKind
    public let endpoint: CmxAttachEndpoint
    public let priority: Int

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        try self.init(
            id: container.decode(String.self, forKey: .id),
            kind: container.decode(CmxAttachTransportKind.self, forKey: .kind),
            endpoint: container.decode(CmxAttachEndpoint.self, forKey: .endpoint),
            priority: container.decodeIfPresent(Int.self, forKey: .priority) ?? 0
        )
    }

    public init(
        id: String,
        kind: CmxAttachTransportKind,
        endpoint: CmxAttachEndpoint,
        priority: Int = 0
    ) throws {
        self.id = id
        self.kind = kind
        self.endpoint = endpoint
        self.priority = priority
        try validate()
    }

    /// Validates that the endpoint shape and route kind agree.
    public func validate() throws {
        switch endpoint {
        case let .hostPort(host, port):
            guard !host.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
                throw CmxAttachRouteError.emptyHost
            }
            guard (1...65535).contains(port) else {
                throw CmxAttachRouteError.invalidPort(port)
            }
        case let .peer(identity, pathHints):
            guard !identity.endpointID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
                throw CmxAttachRouteError.emptyPeerID
            }
            guard pathHints.count <= CmxAttachEndpoint.maximumIrohPathHintCount else {
                throw CmxAttachRouteError.tooManyPeerPathHints(
                    actual: pathHints.count,
                    maximum: CmxAttachEndpoint.maximumIrohPathHintCount
                )
            }
            for pathHint in pathHints {
                do {
                    try pathHint.validate()
                } catch CmxIrohPathHintError.emptyValue {
                    switch pathHint.kind {
                    case .directAddress:
                        throw CmxAttachRouteError.emptyPeerAddress
                    case .relayIdentifier, .relayURL:
                        throw CmxAttachRouteError.emptyURL
                    }
                }
            }
        case let .url(url):
            guard !url.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
                throw CmxAttachRouteError.emptyURL
            }
        }

        switch (kind, endpoint) {
        case (.tailscale, .hostPort), (.debugLoopback, .hostPort), (.iroh, .peer), (.websocket, .url):
            break
        default:
            throw CmxAttachRouteError.endpointMismatch(kind: kind, endpoint: endpoint)
        }
    }

}

public enum CmxAttachTicketError: Error, Equatable, Sendable {
    case unsupportedVersion(Int)
    case noRoutes
    case emptyAuthToken
}

public struct CmxAttachTicket: Codable, Equatable, Sendable {
    public static let currentVersion = 1

    /// The canonical on-the-wire keys. Most fields use camelCase; the auth
    /// token field is the one historical exception (`auth_token`).
    ///
    /// Encoding stays byte-compatible with what the mac side of PR 5079 already
    /// produces and decodes (this exact type is shared by both the iOS and mac
    /// app via `CMUXMobileCore`), so the mixed convention is preserved on the
    /// encode path. Decoding is tolerant: it accepts both the canonical
