        while (payloadRead < payloadLen) {
            val n = inp.read(payloadBuf, payloadRead, payloadLen - payloadRead)
            if (n == -1) return@withContext null
            payloadRead += n
        }
        payloadBuf
    }

    override fun close() {
        socket?.close()
        socket = null
        inputStream = null
        outputStream = null
    }

    val isConnected: Boolean get() = socket?.isConnected == true && socket?.isClosed == false
}

