package dev.cmux.termux

/**
 * Minimal VT100/ANSI terminal emulator for the cmux Android demo.
 *
 * This is a simplified stand-in for the full Termux terminal-emulator library.
 * For production, vendor the full Termux terminal-emulator Gradle module from
 * https://github.com/termux/termux-app/tree/master/terminal-emulator and replace
 * this class with TerminalSession + TerminalEmulator from that library.
 *
 * The interface here mirrors Termux's TerminalEmulator API so the feature module
 * can call `emulator.feed(bytes)` and `emulator.screen` identically.
 */
class TerminalEmulator(
    var columns: Int = 80,
    var rows: Int = 24,
) {
    /** Flat array of characters on screen (rows * columns). */
    private val cells = Array(rows) { CharArray(columns) { ' ' } }

    private var cursorRow = 0
    private var cursorCol = 0
    private val pendingEscape = StringBuilder()
    private var inEscape = false

    /** Listeners receive a callback whenever screen state changes. */
    var onChange: (() -> Unit)? = null

    /**
     * Feed raw bytes from the terminal output stream into the emulator.
     * Handles basic ANSI escape sequences (cursor movement, clear screen, SGR).
     */
    fun feed(data: ByteArray) {
        for (byte in data) {
            val ch = byte.toInt().and(0xFF).toChar()
            processChar(ch)
        }
        onChange?.invoke()
    }

    /** Return the current screen as a list of strings (one per row). */
    val screen: List<String>
        get() = cells.map { String(it) }

    /** Return raw text content (for testing). */
    fun screenText(): String = screen.joinToString("\n")

    fun resize(columns: Int, rows: Int) {
        this.columns = columns
        this.rows = rows
        // Re-init cells; real implementation would reflow
    }

    private fun processChar(ch: Char) {
        when {
            inEscape -> handleEscape(ch)
            ch == '\u001B' -> {
                inEscape = true
                pendingEscape.clear()
                pendingEscape.append(ch)
            }
            ch == '\n' -> {
                cursorRow = (cursorRow + 1).coerceAtMost(rows - 1)
                if (cursorRow == rows - 1) scrollUp()
            }
            ch == '\r' -> cursorCol = 0
            ch == '\b' -> cursorCol = (cursorCol - 1).coerceAtLeast(0)
            ch >= ' ' -> {
                if (cursorRow < rows && cursorCol < columns) {
                    cells[cursorRow][cursorCol] = ch
                    cursorCol++
                    if (cursorCol >= columns) {
                        cursorCol = 0
                        cursorRow = (cursorRow + 1).coerceAtMost(rows - 1)
                    }
                }
            }
        }
    }

    private fun handleEscape(ch: Char) {
        pendingEscape.append(ch)
        val seq = pendingEscape.toString()
        when {
            seq == "\u001B[2J" -> { clearScreen(); inEscape = false }
            seq == "\u001Bc" -> { clearScreen(); inEscape = false }
            seq.matches(Regex("\u001B\\[\\d*;?\\d*H")) -> {
                // Cursor position: ESC[row;colH
                val parts = seq.removePrefix("\u001B[").removeSuffix("H").split(";")
                cursorRow = ((parts.getOrNull(0)?.toIntOrNull() ?: 1) - 1).coerceAtLeast(0).coerceAtMost(rows - 1)
                cursorCol = ((parts.getOrNull(1)?.toIntOrNull() ?: 1) - 1).coerceAtLeast(0).coerceAtMost(columns - 1)
                inEscape = false
            }
            seq.matches(Regex("\u001B\\[\\d*m")) -> {
                // SGR color/attribute — ignore for demo
                inEscape = false
            }
            seq.length > 16 -> inEscape = false // bail on overlong sequences
        }
    }

    private fun clearScreen() {
        for (row in cells) row.fill(' ')
        cursorRow = 0
        cursorCol = 0
    }

    private fun scrollUp() {
        for (i in 0 until rows - 1) cells[i] = cells[i + 1].copyOf()
        cells[rows - 1].fill(' ')
    }
}

package dev.cmux.android.feature.pairing

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dagger.hilt.android.lifecycle.HiltViewModel
import dev.cmux.android.core.auth.StackAuthTokenStore
import dev.cmux.android.core.pairing.AttachRoute
import dev.cmux.android.core.pairing.AttachTicket
import dev.cmux.android.core.pairing.AttachTicketDecoder
import dev.cmux.android.core.pairing.PairedMacStore
import dev.cmux.android.core.rpc.MobileCoreRpcSession
import dev.cmux.android.core.transport.TcpByteTransport
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import javax.inject.Inject

sealed interface PairingState {
    data object Idle : PairingState
    data object Scanning : PairingState
    data class Connecting(val host: String, val port: Int) : PairingState
    data class Success(val displayName: String?) : PairingState
    data class Error(val message: String) : PairingState
}

@HiltViewModel
class PairingViewModel @Inject constructor(
    private val pairedMacStore: PairedMacStore,
    private val tokenStore: StackAuthTokenStore,
) : ViewModel() {

    private val _state = MutableStateFlow<PairingState>(PairingState.Idle)
    val state: StateFlow<PairingState> = _state.asStateFlow()

    fun startScanning() {
        _state.value = PairingState.Scanning
    }

    fun onQrCodeScanned(rawUrl: String) {
        viewModelScope.launch(Dispatchers.IO) {
            when (val decoded = AttachTicketDecoder.decode(rawUrl)) {
                is AttachTicketDecoder.Result.Error -> {
                    _state.value = PairingState.Error("Invalid QR: ${decoded.reason}")
                }
                is AttachTicketDecoder.Result.Success -> {
                    connectAndPair(decoded.ticket)
                }
            }
        }
    }

    private suspend fun connectAndPair(ticket: AttachTicket) {
        val route = ticket.routes.firstOrNull { it.kind == AttachRoute.RouteKind.TAILSCALE }
            ?: ticket.routes.firstOrNull()
            ?: run {
                _state.value = PairingState.Error("No usable route in ticket")
                return
            }

        // In emulator: replace Tailscale host with 10.0.2.2 for local debugging.
        val host = if (isEmulator() && route.kind == AttachRoute.RouteKind.TAILSCALE) {
            EMULATOR_HOST
        } else {
            route.host
        }
        val port = if (route.port > 0) route.port else DEFAULT_PORT

        _state.value = PairingState.Connecting(host, port)

        try {
            val transport = TcpByteTransport(host, port)
            val session = MobileCoreRpcSession(transport)
            session.connect()

            // Send mobile.host.status (no auth required)
            val statusResponse = session.sendRequest("mobile.host.status")
            val result = statusResponse["result"]?.jsonObject
            val macDeviceId = result?.get("mac_device_id")?.jsonPrimitive?.content ?: ""
            val displayName = result?.get("mac_display_name")?.jsonPrimitive?.content

            pairedMacStore.save(ticket, macDeviceId, displayName)

            session.disconnect()
            _state.value = PairingState.Success(displayName)
        } catch (e: Exception) {
            _state.value = PairingState.Error("Connection failed: ${e.message}")
        }
    }

    fun reset() {
        _state.value = PairingState.Idle
    }

    private fun isEmulator(): Boolean {
        return android.os.Build.FINGERPRINT.startsWith("generic")
            || android.os.Build.FINGERPRINT.startsWith("unknown")
            || android.os.Build.MODEL.contains("Emulator")
            || android.os.Build.MODEL.contains("Android SDK built for x86")
    }

    companion object {
        const val EMULATOR_HOST = "10.0.2.2"
        const val DEFAULT_PORT = 58465
    }
}

package dev.cmux.android.core.pairing

import java.net.URI
import java.net.URLDecoder

/**
 * Decodes a scanned cmux pairing QR URL into an [AttachTicket].
 *
 * Supported grammars:
 *  - v2 (Tailscale): `cmux-ios://attach?v=2&ub=<uid>&pc=<compat>&r=<host>:<port>[&r=...]`
 *  - v3 (Iroh): `cmux-ios://attach?v=3&i=<endpoint-id>[&d=<device-id>]`
 *
 * Scheme variants accepted: `cmux-ios`, `cmux-ios-dev` (dev builds).
 * Loopback hosts (127.0.0.1, localhost, ::1) are rejected to prevent the phone
 * from dialling itself.
 *
 * Uses java.net.URI for parsing (JVM-compatible, no Android dependency) so this
 * class is fully testable in JVM unit tests without Robolectric.
 */
object AttachTicketDecoder {

    private val ACCEPTED_SCHEMES = setOf("cmux-ios", "cmux-ios-dev")
    private val LOOPBACK_HOSTS = setOf("127.0.0.1", "localhost", "::1", "[::1]")
    private const val MAX_ROUTES = 8

    sealed class Result {
        data class Success(val ticket: AttachTicket) : Result()
        data class Error(val reason: DecodeError) : Result()
    }

    enum class DecodeError {
        INVALID_URL,
        UNSUPPORTED_VERSION,
        LOOPBACK_ROUTE_REJECTED,
        EMPTY_ROUTES,
        INVALID_PORT,
    }

    fun decode(rawUrl: String): Result {
        val uri = try {
            URI(rawUrl)
        } catch (e: Exception) {
            return Result.Error(DecodeError.INVALID_URL)
        }

        val scheme = uri.scheme?.lowercase() ?: return Result.Error(DecodeError.INVALID_URL)
        if (scheme !in ACCEPTED_SCHEMES) return Result.Error(DecodeError.INVALID_URL)
        if (uri.host != "attach") return Result.Error(DecodeError.INVALID_URL)

        val params = parseQueryParams(uri.rawQuery ?: "")
        val version = params["v"]?.firstOrNull()?.toIntOrNull()
            ?: return Result.Error(DecodeError.INVALID_URL)

        return when (version) {
            2 -> decodeV2(params)
            3 -> decodeV3(params)
            else -> Result.Error(DecodeError.UNSUPPORTED_VERSION)
        }
    }

    private fun decodeV2(params: Map<String, List<String>>): Result {
        val rawRoutes = params["r"] ?: emptyList()
        if (rawRoutes.isEmpty() || rawRoutes.size > MAX_ROUTES) {
            return Result.Error(DecodeError.EMPTY_ROUTES)
        }

        val routes = mutableListOf<AttachRoute>()
        for (rawRoute in rawRoutes) {
            val decoded = URLDecoder.decode(rawRoute, "UTF-8")
            val (host, port) = parseHostPort(decoded)
                ?: return Result.Error(DecodeError.INVALID_URL)
            if (port !in 1..65535) return Result.Error(DecodeError.INVALID_PORT)
            if (isLoopback(host)) return Result.Error(DecodeError.LOOPBACK_ROUTE_REJECTED)
            routes.add(AttachRoute(kind = AttachRoute.RouteKind.TAILSCALE, host = host, port = port))
        }

        val userId = params["ub"]?.firstOrNull()?.takeIf { it.isNotBlank() }
        val compat = params["pc"]?.firstOrNull()?.toIntOrNull() ?: 0

        return Result.Success(
            AttachTicket(routes = routes, macUserId = userId, compatibilityVersion = compat)
        )
    }

    private fun decodeV3(params: Map<String, List<String>>): Result {
        val endpointId = params["i"]?.firstOrNull()?.takeIf { it.isNotBlank() }
            ?: return Result.Error(DecodeError.INVALID_URL)
        val deviceId = params["d"]?.firstOrNull()?.takeIf { it.isNotBlank() } ?: ""

        val route = AttachRoute(
            kind = AttachRoute.RouteKind.IROH_ENDPOINT,
            host = endpointId,
            port = 0,
        )
        return Result.Success(
            AttachTicket(routes = listOf(route), macUserId = null, macDeviceId = deviceId)
        )
    }

    /**
     * Parse query string into a multi-value map.
     * Handles repeated keys (e.g., `r=host1&r=host2`).
     */
    private fun parseQueryParams(query: String): Map<String, List<String>> {
        if (query.isBlank()) return emptyMap()
        val result = mutableMapOf<String, MutableList<String>>()
        query.split("&").forEach { pair ->
            val idx = pair.indexOf('=')
            if (idx < 0) return@forEach
            val key = URLDecoder.decode(pair.substring(0, idx), "UTF-8")
            val value = URLDecoder.decode(pair.substring(idx + 1), "UTF-8")
            result.getOrPut(key) { mutableListOf() }.add(value)
        }
        return result
    }

    /** Parse `host:port` or `[ipv6]:port`. Returns null on malformed input. */
    private fun parseHostPort(raw: String): Pair<String, Int>? {
        val trimmed = raw.trim()
        return if (trimmed.startsWith("[")) {
            // IPv6: [addr]:port
            val closing = trimmed.indexOf(']')
            if (closing < 0) return null
            val host = trimmed.substring(1, closing)
            val rest = trimmed.substring(closing + 1)
            if (!rest.startsWith(":")) return null
            val port = rest.substring(1).toIntOrNull() ?: return null
            host to port
        } else {
            val idx = trimmed.lastIndexOf(':')
            if (idx < 0) return null
            val host = trimmed.substring(0, idx)
            val port = trimmed.substring(idx + 1).toIntOrNull() ?: return null
            host to port
        }
    }

    private fun isLoopback(host: String): Boolean = host.lowercase() in LOOPBACK_HOSTS
}

