    28→    static func callbackScheme(
    29→        environment: [String: String],
    30→        bundleIdentifier: String?,
    31→        isDebugBuild: Bool
    32→    ) -> String {
    33→        if let overridden = environment["CMUX_AUTH_CALLBACK_SCHEME"]?
    34→            .trimmingCharacters(in: .whitespacesAndNewlines),
    35→           !overridden.isEmpty {
    36→            return overridden
    37→        }
    38→        if isDebugBuild {
    39→            // Untagged Debug builds register cmux-dev:// so they can coexist
    40→            // with the installed stable app. Tagged Debug builds use
    41→            // cmux-dev-<tag>://.
    42→            if let tag = environment["CMUX_TAG"]?
    43→                .trimmingCharacters(in: .whitespacesAndNewlines),
    44→               !tag.isEmpty,
    45→               let schemeTag = sanitizedCallbackSchemeTag(tag) {
    46→                return "cmux-dev-\(schemeTag)"
    47→            }
    48→            return "cmux-dev"
    49→        }
    50→        if bundleIdentifier == "com.cmuxterm.app.nightly" {
    51→            return "cmux-nightly"
    52→        }
    53→        return "cmux"
    54→    }
