    56→    static func sanitizedCallbackSchemeTag(_ rawTag: String) -> String? {
    57→        let lowercased = rawTag.lowercased()
    58→        var result = ""
    59→        var previousWasHyphen = false
    60→        for scalar in lowercased.unicodeScalars {
    61→            let isAllowed = (scalar.value >= 97 && scalar.value <= 122)
    62→                || (scalar.value >= 48 && scalar.value <= 57)
    63→            if isAllowed {
    64→                result.unicodeScalars.append(scalar)
    65→                previousWasHyphen = false
    66→            } else if !previousWasHyphen {
    67→                result.append("-")
    68→                previousWasHyphen = true
    69→            }
    70→        }
    71→        result = result.trimmingCharacters(in: CharacterSet(charactersIn: "-"))
    72→        return result.isEmpty ? nil : result
    73→    }
