   130→    static func resolvedAppSessionHandoffOrigin(
   131→        environment: [String: String],
   132→        isDebugBuild: Bool
   133→    ) -> URL {
   134→        let productionOrigin = URL(string: "https://cmux.com")!
   135→        guard isDebugBuild else { return productionOrigin }
   136→
   137→        let candidate = canonicalizedLoopbackURL(appWebOrigin(environment: environment))
   138→        if candidate == productionOrigin { return productionOrigin }
   139→        guard let components = URLComponents(
   140→            url: candidate,
   141→            resolvingAgainstBaseURL: false
   142→        ),
   143→              components.scheme == "http" || components.scheme == "https",
   144→              components.host?.lowercased() == "localhost",
   145→              components.user == nil,
   146→              components.password == nil,
   147→              components.path.isEmpty || components.path == "/",
   148→              components.query == nil,
   149→              components.fragment == nil else {
   150→            return productionOrigin
   151→        }
   152→        return candidate
   153→    }
