   324→    static func resolvedIrohBrokerBaseURL(
   325→        environment: [String: String],
   326→        isDebugBuild: Bool
   327→    ) -> URL? {
   328→        if let explicit = environment["CMUX_IROH_BROKER_BASE_URL"]?
   329→            .trimmingCharacters(in: .whitespacesAndNewlines),
   330→           !explicit.isEmpty {
   331→            return validatedIrohBrokerURL(explicit)
   332→        }
   333→        let fallback = isDebugBuild
   334→            ? "https://cmux-staging.vercel.app"
   335→            : "https://cmux.com"
