   339→    private static func validatedIrohBrokerURL(_ rawValue: String) -> URL? {
   340→        guard let url = URL(string: rawValue),
   341→              let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
   342→              let scheme = components.scheme?.lowercased(),
   343→              let host = components.host?.lowercased(),
   344→              components.user == nil,
   345→              components.password == nil,
   346→              components.query == nil,
   347→              components.fragment == nil else {
   348→            return nil
   349→        }
   350→        if scheme == "https" { return url }
   351→        guard scheme == "http",
   352→              ["127.0.0.1", "::1", "localhost"].contains(host) else {
   353→            return nil
   354→        }
   355→        return canonicalizedLoopbackURL(url)
   356→    }
