   358→    /// Look up `key=value` in `~/.cmux-dev.env` for the DEBUG build. Returns nil in Release.
   359→    /// Kept tiny on purpose — this is a "drop a file, restart the app, it picks up" override,
   360→    /// not a real config system.
   361→    private static func devOverride(key: String) -> String? {
   362→        #if DEBUG
   363→        guard let home = ProcessInfo.processInfo.environment["HOME"] else { return nil }
   364→        let path = (home as NSString).appendingPathComponent(".cmux-dev.env")
   365→        guard let data = try? String(contentsOfFile: path, encoding: .utf8) else { return nil }
   366→        for raw in data.split(separator: "\n") {
   367→            let line = raw.trimmingCharacters(in: .whitespaces)
   368→            guard !line.hasPrefix("#"), let eq = line.firstIndex(of: "=") else { continue }
   369→            let k = String(line[..<eq]).trimmingCharacters(in: .whitespaces)
   370→            guard k == key else { continue }
   371→            var v = String(line[line.index(after: eq)...]).trimmingCharacters(in: .whitespaces)
   372→            if v.hasPrefix("\"") && v.hasSuffix("\"") { v = String(v.dropFirst().dropLast()) }
   373→            if v.hasPrefix("'") && v.hasSuffix("'") { v = String(v.dropFirst().dropLast()) }
   374→            return v.isEmpty ? nil : v
   375→        }
   376→        return nil
   377→        #else
   378→        return nil
   379→        #endif
   380→    }
