   569→        if let clientKey = environment["CMUX_STACK_PUBLISHABLE_CLIENT_KEY"]?
   570→            .trimmingCharacters(in: .whitespacesAndNewlines),
   571→           !clientKey.isEmpty {
   572→            return clientKey
   573→        }
   574→        switch resolvedStackAuthEnvironment(
   575→            environment: environment,
   576→            isDebugBuild: isDebugBuild
   577→        ) {
   578→        case .development:
   579→            return developmentStackPublishableClientKey
   580→        case .production:
   581→            return productionStackPublishableClientKey
   582→        }
   583→    }
   584→
   585→    /// The website origin used for the after-sign-in handler.
   586→    static var afterSignInOrigin: URL {
   587→        resolvedAfterSignInOrigin(environment: ProcessInfo.processInfo.environment)
   588→    }
   589→
   590→    static func resolvedAfterSignInOrigin(environment: [String: String]) -> URL {
   591→        resolvedURL(
   592→            environmentKey: "CMUX_AUTH_WWW_ORIGIN",
   593→            fallback: resolvedDefaultWebOrigin(environment: environment),
   594→            environment: environment
   595→        )
   596→    }
   597→
   598→    static func signInURL(callbackState: String? = nil) -> URL {
   599→        signInURL(callbackState: callbackState, afterSignInOrigin: afterSignInOrigin, callbackURL: callbackURL)
   600→    }
   601→
   602→    static func signInURL(
   603→        callbackState: String? = nil,
   604→        environment: [String: String],
   605→        bundleIdentifier: String? = nil
   606→    ) -> URL {
   607→        signInURL(
   608→            callbackState: callbackState,
   609→            afterSignInOrigin: resolvedAfterSignInOrigin(environment: environment),
   610→            callbackURL: resolvedCallbackURL(environment: environment, bundleIdentifier: bundleIdentifier)
   611→        )
   612→    }
   613→
   614→    private static func signInURL(
   615→        callbackState: String?,
   616→        afterSignInOrigin: URL,
   617→        callbackURL: URL
   618→    ) -> URL {
   619→        // Build the after-sign-in callback URL that includes the native app return scheme.
   620→        // The after-sign-in handler extracts tokens from the Stack Auth session
   621→        // and redirects to the native app via the cmux:// callback scheme.
   622→        var afterSignInComponents = URLComponents(
   623→            url: afterSignInOrigin.appendingPathComponent("handler/after-sign-in", isDirectory: false),
   624→            resolvingAgainstBaseURL: false
   625→        )!
   626→        var nativeCallbackComponents = URLComponents(url: callbackURL, resolvingAgainstBaseURL: false)!
   627→        if let callbackState {
   628→            nativeCallbackComponents.queryItems = [
   629→                URLQueryItem(name: "cmux_auth_state", value: callbackState),
   630→            ]
   631→        }
   632→
   633→        afterSignInComponents.queryItems = [
   634→            URLQueryItem(
   635→                name: "native_app_return_to",
   636→                value: nativeCallbackComponents.url!.absoluteString
   637→            ),
   638→        ]
   639→
   640→        // Enter through cmux's native sign-in wrapper, which sets a short-lived
   641→        // server-side handoff nonce before redirecting to Stack's /sign-in.
   642→        var components = URLComponents(
   643→            url: afterSignInOrigin.appendingPathComponent("handler/native-sign-in", isDirectory: false),
   644→            resolvingAgainstBaseURL: false
   645→        )!
   646→        components.queryItems = [
   647→            URLQueryItem(
   648→                name: "after_auth_return_to",
   649→                value: afterSignInComponents.url!.absoluteString
   650→            ),
   651→        ]
   652→        return components.url!
   653→    }
   654→
   655→    private static func resolvedURL(environmentKey: String, fallback: String) -> URL {
   656→        resolvedURL(
   657→            environmentKey: environmentKey,
   658→            fallback: fallback,
   659→            environment: ProcessInfo.processInfo.environment
   660→        )
   661→    }
