   669→            .trimmingCharacters(in: .whitespacesAndNewlines),
   670→           !overridden.isEmpty,
   671→           let url = URL(string: overridden) {
   672→            return url
   673→        }
   674→        return URL(string: fallback)!
   675→    }
   676→
   677→    private static func environmentURL(_ key: String, environment: [String: String]) -> URL? {
   678→        guard let raw = environment[key]?.trimmingCharacters(in: .whitespacesAndNewlines),
   679→              !raw.isEmpty
   680→        else {
   681→            return nil
   682→        }
   683→        return URL(string: raw)
   684→    }
