   152→    private static func cacheKey(for accessToken: String) -> String {
   153→        // Pure-Swift byte-to-hex (no String(format:)) — this runs for every
   154→        // authorized mobile RPC (incl. per-keystroke terminal.input) before the
   155→        // verifier cache hit, so it must stay allocation-cheap. String(format:)
   156→        // here would reintroduce the PR #5347 hot-path memory-growth crash class.
   157→        let digest = Array(SHA256.hash(data: Data(accessToken.utf8)))
   158→        let hexDigits: [UInt8] = Array("0123456789abcdef".utf8)
   159→        var hex = [UInt8]()
   160→        hex.reserveCapacity(digest.count * 2)
   161→        for byte in digest {
   162→            hex.append(hexDigits[Int(byte >> 4)])
   163→            hex.append(hexDigits[Int(byte & 0x0F)])
   164→        }
   165→        return String(decoding: hex, as: UTF8.self)
   166→    }
