                        verticalArrangement = Arrangement.spacedBy(12.dp),
                    ) {
                        Text("Error: ${s.message}")
                        Button(onClick = { viewModel.refresh() }) { Text("Retry") }
                    }
                }
                is WorkspaceUiState.Loaded -> {
                    if (s.workspaces.isEmpty()) {
                        Text(
                            "No workspaces found",
                            modifier = Modifier.align(Alignment.Center),
