                        LazyColumn(modifier = Modifier.fillMaxSize()) {
                            items(s.workspaces) { ws ->
                                WorkspaceRow(
                                    workspace = ws,
                                    onOpenTerminal = { surfaceId ->
                                        onOpenTerminal(ws.id, surfaceId)
                                    },
                                    onOpenBrowser = { panelId ->
