public import Foundation

/// Typed decoder for the `mobile.events.subscribe` RPC result.
///
/// The Mac acknowledges a subscription by echoing back the `stream_id` it
/// registered. A non-empty `stream_id` is the success signal the listener loop
/// keys off; an absent or empty value means the subscription did not take.
public struct MobileEventSubscribeResponse: Decodable, Sendable {
    /// The server-registered event stream identifier.
    ///
    /// Empty or missing when the subscription was not accepted.
    public let streamID: String

    /// Whether the host already had a registration for this `stream_id` on
    /// this connection before processing the request (`mobile.events.subscribe`
    /// is idempotent per stream id).
    ///
    /// `false` means this acknowledgement INSTALLED the registration, so any
    /// events emitted while it was absent were never delivered; the liveness
    /// probe uses that to trigger a catch-up replay. `nil` when the host
    /// predates the field, which callers must treat as "unknown, assume it was
    /// already active" so older Macs keep today's behavior.
    public let alreadySubscribed: Bool?

    /// The selected event delivery path, absent on older hosts.
    public let eventTransport: String?

    private enum CodingKeys: String, CodingKey {
        case streamID = "stream_id"
        case alreadySubscribed = "already_subscribed"
        case eventTransport = "event_transport"
    }

    /// Decode a subscribe acknowledgement from raw JSON data.
    ///
    /// Tolerant of a missing `stream_id` (decodes to an empty string) so a
    /// malformed acknowledgement is treated as "not subscribed" rather than a
    /// thrown error the caller would have to special-case.
    /// - Parameter data: The RPC result payload.
    /// - Returns: The decoded acknowledgement.
    /// - Throws: A decoding error only if the payload is not a JSON object.
    public static func decode(_ data: Data) throws -> MobileEventSubscribeResponse {
        try JSONDecoder().decode(Self.self, from: data)
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        streamID = (try container.decodeIfPresent(String.self, forKey: .streamID)) ?? ""
        alreadySubscribed = try container.decodeIfPresent(Bool.self, forKey: .alreadySubscribed)
        eventTransport = try container.decodeIfPresent(String.self, forKey: .eventTransport)
    }
}

package dev.cmux.android.feature.terminal

import androidx.lifecycle.SavedStateHandle
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dagger.hilt.android.lifecycle.HiltViewModel
import dev.cmux.android.core.auth.StackAuthTokenStore
import dev.cmux.android.core.pairing.PairedMacStore
import dev.cmux.android.core.rpc.MobileCoreRpcSession
import dev.cmux.android.core.transport.TcpByteTransport
import dev.cmux.termux.TerminalEmulator
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.put
import android.util.Base64
import javax.inject.Inject

sealed interface TerminalUiState {
    data object Connecting : TerminalUiState
    data class Connected(val lines: List<String>) : TerminalUiState
    data class Error(val message: String) : TerminalUiState
}

@HiltViewModel
class TerminalViewModel @Inject constructor(
    savedStateHandle: SavedStateHandle,
    private val pairedMacStore: PairedMacStore,
    private val tokenStore: StackAuthTokenStore,
) : ViewModel() {

    private val workspaceId: String = checkNotNull(savedStateHandle["workspaceId"])
    private val surfaceId: String = checkNotNull(savedStateHandle["surfaceId"])

    private val emulator = TerminalEmulator(columns = 80, rows = 24)
    private val _state = MutableStateFlow<TerminalUiState>(TerminalUiState.Connecting)
    val state: StateFlow<TerminalUiState> = _state.asStateFlow()

    private var session: MobileCoreRpcSession? = null

    init {
        emulator.onChange = {
            _state.value = TerminalUiState.Connected(emulator.screen)
        }
        connect()
    }

    private fun connect() {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val mac = pairedMacStore.getLatest()
                    ?: return@launch run { _state.value = TerminalUiState.Error("No paired Mac") }

                val transport = TcpByteTransport(mac.primaryHost, mac.primaryPort)
                val rpcSession = MobileCoreRpcSession(transport)
                rpcSession.connect()
                session = rpcSession

                // Subscribe to terminal.bytes events
                val collectJob = viewModelScope.launch(Dispatchers.IO) {
                    rpcSession.events.collect { envelope ->
                        if (envelope.topic == "terminal.bytes") {
                            val dataB64 = envelope.payload["data"]?.jsonPrimitive?.content
                            if (dataB64 != null) {
                                val bytes = Base64.decode(dataB64, Base64.DEFAULT)
                                emulator.feed(bytes)
                            }
                        }
                    }
                }

                // Subscribe to events stream
                val accessToken = tokenStore.getAccessToken()
                rpcSession.sendRequest(
                    method = "mobile.events.subscribe",
                    params = mapOf(
                        "topics" to JsonPrimitive("terminal.bytes"),
                        "surface_id" to JsonPrimitive(surfaceId),
                    ),
                    authToken = accessToken,
                )

                // Request terminal replay to get current screen
                rpcSession.sendRequest(
                    method = "mobile.terminal.replay",
                    params = mapOf(
                        "surface_id" to JsonPrimitive(surfaceId),
                        "workspace_id" to JsonPrimitive(workspaceId),
                    ),
                    authToken = accessToken,
                )

                _state.value = TerminalUiState.Connected(emulator.screen)
            } catch (e: Exception) {
                _state.value = TerminalUiState.Error(e.message ?: "Connection failed")
            }
        }
    }

    /** Send keyboard input to the terminal. */
    fun sendInput(text: String) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val rpc = session ?: return@launch
                val encoded = Base64.encodeToString(text.toByteArray(), Base64.NO_WRAP)
                rpc.sendRequest(
                    method = "mobile.terminal.input",
                    params = mapOf(
                        "surface_id" to JsonPrimitive(surfaceId),
                        "workspace_id" to JsonPrimitive(workspaceId),
                        "data" to JsonPrimitive(encoded),
                    ),
                    authToken = tokenStore.getAccessToken(),
                )
            } catch (e: Exception) {
                // Input delivery failure is non-fatal
            }
        }
    }

    /** Feed raw bytes into the emulator. Used by tests to bypass the network. */
    fun feedBytesForTest(bytes: ByteArray) {
        emulator.feed(bytes)
    }

    override fun onCleared() {
        super.onCleared()
        session?.disconnect()
    }
}

package dev.cmux.android.feature.terminal

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.text.BasicTextField
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.ArrowBack
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.TextStyle
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.lifecycle.compose.collectAsStateWithLifecycle

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TerminalScreen(
    workspaceId: String,
    surfaceId: String,
    onBack: () -> Unit,
    viewModel: TerminalViewModel = hiltViewModel(),
) {
    val state by viewModel.state.collectAsStateWithLifecycle()
    var inputText by remember { mutableStateOf("") }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Terminal", fontFamily = FontFamily.Monospace) },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
            )
        },
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .background(Color(0xFF0D0D0D)),
        ) {
            when (val s = state) {
                is TerminalUiState.Connecting -> {
                    Box(modifier = Modifier.weight(1f), contentAlignment = Alignment.Center) {
                        CircularProgressIndicator()
                    }
                }
                is TerminalUiState.Error -> {
                    Box(modifier = Modifier.weight(1f), contentAlignment = Alignment.Center) {
                        Text("Error: ${s.message}", color = Color.Red)
                    }
                }
                is TerminalUiState.Connected -> {
                    // Terminal output
                    LazyColumn(
                        modifier = Modifier
                            .weight(1f)
                            .fillMaxWidth()
                            .padding(8.dp),
                        reverseLayout = false,
                    ) {
                        items(s.lines) { line ->
                            Text(
                                text = line,
                                fontFamily = FontFamily.Monospace,
                                fontSize = 13.sp,
                                color = Color(0xFFD4D4D4),
                                modifier = Modifier.fillMaxWidth(),
                            )
                        }
                    }
                }
            }

            // Input row
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(Color(0xFF1E1E1E))
                    .padding(horizontal = 8.dp, vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                BasicTextField(
                    value = inputText,
                    onValueChange = { inputText = it },
                    textStyle = TextStyle(
                        color = Color.White,
                        fontFamily = FontFamily.Monospace,
                        fontSize = 13.sp,
                    ),
                    modifier = Modifier.weight(1f),
                    singleLine = true,
                )
                Spacer(Modifier.width(8.dp))
                Button(
                    onClick = {
                        viewModel.sendInput(inputText + "\n")
                        inputText = ""
                    },
                ) {
                    Text("Send")
                }
            }
        }
    }
}

