/// Typed decoder for the `mobile.events.subscribe` RPC result.
///
/// The Mac acknowledges a subscription by echoing back the `stream_id` it
/// registered. A non-empty `stream_id` is the success signal the listener loop
/// keys off; an absent or empty value means the subscription did not take.
public struct MobileEventSubscribeResponse: Decodable, Sendable {
    /// The server-registered event stream identifier.
    ///
    /// Empty or missing when the subscription was not accepted.
    public let streamID: String

    /// Whether the host already had a registration for this `stream_id` on
    /// this connection before processing the request (`mobile.events.subscribe`
    /// is idempotent per stream id).
    ///
    /// `false` means this acknowledgement INSTALLED the registration, so any
    /// events emitted while it was absent were never delivered; the liveness
    /// probe uses that to trigger a catch-up replay. `nil` when the host
    /// predates the field, which callers must treat as "unknown, assume it was
    /// already active" so older Macs keep today's behavior.
    public let alreadySubscribed: Bool?

    /// The selected event delivery path, absent on older hosts.
    public let eventTransport: String?

    private enum CodingKeys: String, CodingKey {
        case streamID = "stream_id"
        case alreadySubscribed = "already_subscribed"
        case eventTransport = "event_transport"
    }

    /// Decode a subscribe acknowledgement from raw JSON data.
    ///
    /// Tolerant of a missing `stream_id` (decodes to an empty string) so a
    /// malformed acknowledgement is treated as "not subscribed" rather than a
    /// thrown error the caller would have to special-case.
    /// - Parameter data: The RPC result payload.
    /// - Returns: The decoded acknowledgement.
    /// - Throws: A decoding error only if the payload is not a JSON object.
    public static func decode(_ data: Data) throws -> MobileEventSubscribeResponse {
        try JSONDecoder().decode(Self.self, from: data)
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        streamID = (try container.decodeIfPresent(String.self, forKey: .streamID)) ?? ""
        alreadySubscribed = try container.decodeIfPresent(Bool.self, forKey: .alreadySubscribed)
        eventTransport = try container.decodeIfPresent(String.self, forKey: .eventTransport)
    }
}

package dev.cmux.android.core.rpc

import dev.cmux.android.core.transport.TcpByteTransport
import kotlin.coroutines.coroutineContext
import kotlinx.coroutines.*
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.serialization.json.*
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap

/**
 * Multiplexed JSON-RPC session over one persistent TCP connection.
 *
 * Callers use [sendRequest] for request-response RPCs and [events] to
 * observe server-pushed event envelopes.
 *
 * Thread-safety: [sendRequest] and [sendRequestRaw] are coroutine-safe.
 * [connect] / [disconnect] must be called once each.
 */
class MobileCoreRpcSession(
    private val transport: TcpByteTransport,
) {
    private val json = Json { ignoreUnknownKeys = true }
    private val pending = ConcurrentHashMap<String, PendingRequest>()
    private val _events = MutableSharedFlow<EventEnvelope>(extraBufferCapacity = 256)
    val events: SharedFlow<EventEnvelope> = _events.asSharedFlow()

    private var readerJob: Job? = null
    private val scope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    /** Connect the transport and start the background reader loop. */
    suspend fun connect() {
        transport.connect()
        readerJob = scope.launch { readLoop() }
    }

    /** Disconnect and cancel all pending requests. */
    fun disconnect() {
        readerJob?.cancel()
        scope.cancel()
        transport.close()
        pending.values.forEach { it.completion.cancel() }
        pending.clear()
    }

    /**
     * Send a JSON-RPC request and await its response.
     *
     * @param method The RPC method name (e.g. "mobile.workspace.list").
     * @param params Parameters map. The session injects a unique "id".
     * @param authToken Stack auth access token (required for most methods).
     * @return The full JSON response object.
     */
    suspend fun sendRequest(
        method: String,
        params: Map<String, JsonElement> = emptyMap(),
        authToken: String? = null,
    ): JsonObject {
        val id = UUID.randomUUID().toString()
        val requestObj = buildJsonObject {
            put("id", id)
            put("method", method)
            put("params", buildJsonObject { params.forEach { (k, v) -> put(k, v) } })
            if (authToken != null) {
                put("auth", buildJsonObject { put("stack_access_token", authToken) })
            }
        }
        return sendRequestRaw(id, requestObj.toString().toByteArray())
    }

    /** Low-level send with pre-serialized payload. Injects an id if missing. */
    suspend fun sendRequestRaw(
        id: String,
        payload: ByteArray,
    ): JsonObject {
        val deferred = CompletableDeferred<JsonObject>()
        pending[id] = PendingRequest(id, deferred)
        try {
            transport.writeFrame(payload)
            return deferred.await()
        } catch (e: CancellationException) {
            pending.remove(id)
            throw e
        }
    }

    private suspend fun readLoop() {
        try {
            while (coroutineContext.isActive) {
                val raw = transport.readFrame() ?: break
                handleFrame(raw)
            }
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            // Connection lost — cancel all pending with an error
            pending.values.forEach { it.completion.completeExceptionally(e) }
            pending.clear()
        }
    }

    private fun handleFrame(raw: ByteArray) {
        val text = raw.decodeToString()
        val obj = try {
            json.parseToJsonElement(text).jsonObject
        } catch (e: Exception) {
            return
        }

        val id = obj["id"]?.jsonPrimitive?.contentOrNull
        val topic = obj["topic"]?.jsonPrimitive?.contentOrNull

        when {
            // Response to a pending request
            id != null && (obj.containsKey("result") || obj.containsKey("error")) -> {
                pending.remove(id)?.completion?.complete(obj)
            }
            // Server-pushed event
            topic != null -> {
                val payload = obj["payload"]?.jsonObject ?: JsonObject(emptyMap())
                val streamId = obj["stream_id"]?.jsonPrimitive?.contentOrNull
                val envelope = EventEnvelope(topic = topic, payload = payload, stream_id = streamId)
                _events.tryEmit(envelope)
            }
        }
    }
}

