package dev.cmux.termux

/**
 * Minimal VT100/ANSI terminal emulator for the cmux Android demo.
 *
 * This is a simplified stand-in for the full Termux terminal-emulator library.
 * For production, vendor the full Termux terminal-emulator Gradle module from
 * https://github.com/termux/termux-app/tree/master/terminal-emulator and replace
 * this class with TerminalSession + TerminalEmulator from that library.
 *
 * The interface here mirrors Termux's TerminalEmulator API so the feature module
 * can call `emulator.feed(bytes)` and `emulator.screen` identically.
 */
class TerminalEmulator(
    var columns: Int = 80,
    var rows: Int = 24,
) {
    /** Flat array of characters on screen (rows * columns). */
    private val cells = Array(rows) { CharArray(columns) { ' ' } }

    private var cursorRow = 0
    private var cursorCol = 0
    private val pendingEscape = StringBuilder()
    private var inEscape = false

    /** Listeners receive a callback whenever screen state changes. */
    var onChange: (() -> Unit)? = null

    /**
     * Feed raw bytes from the terminal output stream into the emulator.
     * Handles basic ANSI escape sequences (cursor movement, clear screen, SGR).
     */
    fun feed(data: ByteArray) {
        for (byte in data) {
            val ch = byte.toInt().and(0xFF).toChar()
            processChar(ch)
        }
        onChange?.invoke()
    }

    /** Return the current screen as a list of strings (one per row). */
    val screen: List<String>
        get() = cells.map { String(it) }

    /** Return raw text content (for testing). */
    fun screenText(): String = screen.joinToString("\n")

    fun resize(columns: Int, rows: Int) {
        this.columns = columns
        this.rows = rows
        // Re-init cells; real implementation would reflow
    }

    private fun processChar(ch: Char) {
        when {
            inEscape -> handleEscape(ch)
            ch == '\u001B' -> {
                inEscape = true
                pendingEscape.clear()
                pendingEscape.append(ch)
            }
            ch == '\n' -> {
                cursorCol = 0
                if (cursorRow < rows - 1) cursorRow++ else scrollUp()
            }
            ch == '\r' -> cursorCol = 0
            ch == '\b' -> cursorCol = (cursorCol - 1).coerceAtLeast(0)
            ch >= ' ' -> {
                if (cursorRow < rows && cursorCol < columns) {
                    cells[cursorRow][cursorCol] = ch
                    cursorCol++
                    if (cursorCol >= columns) {
                        cursorCol = 0
                        cursorRow = (cursorRow + 1).coerceAtMost(rows - 1)
                    }
                }
            }
        }
    }

    private fun handleEscape(ch: Char) {
        pendingEscape.append(ch)
        val seq = pendingEscape.toString()
        when {
            seq == "\u001B[2J" -> { clearScreen(); inEscape = false }
            seq == "\u001Bc" -> { clearScreen(); inEscape = false }
            seq.matches(Regex("\u001B\\[\\d*;?\\d*H")) -> {
                // Cursor position: ESC[row;colH
                val parts = seq.removePrefix("\u001B[").removeSuffix("H").split(";")
                cursorRow = ((parts.getOrNull(0)?.toIntOrNull() ?: 1) - 1).coerceAtLeast(0).coerceAtMost(rows - 1)
                cursorCol = ((parts.getOrNull(1)?.toIntOrNull() ?: 1) - 1).coerceAtLeast(0).coerceAtMost(columns - 1)
                inEscape = false
            }
            seq.matches(Regex("\u001B\\[\\d*m")) -> {
                // SGR color/attribute — ignore for demo
                inEscape = false
            }
            seq.length > 16 -> inEscape = false // bail on overlong sequences
        }
    }

    private fun clearScreen() {
        for (row in cells) row.fill(' ')
        cursorRow = 0
        cursorCol = 0
    }

    private fun scrollUp() {
        for (i in 0 until rows - 1) cells[i] = cells[i + 1].copyOf()
        cells[rows - 1].fill(' ')
    }
}

package dev.cmux.android.feature.terminal

import androidx.lifecycle.SavedStateHandle
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dagger.hilt.android.lifecycle.HiltViewModel
import dev.cmux.android.core.auth.StackAuthTokenStore
import dev.cmux.android.core.pairing.PairedMacStore
import dev.cmux.android.core.rpc.MobileCoreRpcSession
import dev.cmux.android.core.transport.TcpByteTransport
import dev.cmux.termux.TerminalEmulator
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import android.util.Base64
import java.util.UUID
import javax.inject.Inject

sealed interface TerminalUiState {
    data object Connecting : TerminalUiState
    data class Connected(val lines: List<String>) : TerminalUiState
    data class Error(val message: String) : TerminalUiState
}

@HiltViewModel
class TerminalViewModel @Inject constructor(
    savedStateHandle: SavedStateHandle,
    private val pairedMacStore: PairedMacStore,
    private val tokenStore: StackAuthTokenStore,
) : ViewModel() {

    private val workspaceId: String = checkNotNull(savedStateHandle["workspaceId"])
    private val surfaceId: String = checkNotNull(savedStateHandle["surfaceId"])

    private val emulator = TerminalEmulator(columns = 80, rows = 24)
    private val _state = MutableStateFlow<TerminalUiState>(TerminalUiState.Connecting)
    val state: StateFlow<TerminalUiState> = _state.asStateFlow()

    private var session: MobileCoreRpcSession? = null

    init {
        emulator.onChange = { _state.value = TerminalUiState.Connected(displayLines()) }
        connect()
    }

    private fun displayLines(): List<String> {
        val lines = emulator.screen.map { it.trimEnd() }
        val lastNonBlank = lines.indexOfLast { it.isNotBlank() }
        return if (lastNonBlank < 0) emptyList() else lines.subList(0, lastNonBlank + 1)
    }

    private fun connect() {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val mac = pairedMacStore.getLatest()
                    ?: return@launch run { _state.value = TerminalUiState.Error("No paired Mac") }

                val transport = TcpByteTransport(mac.primaryHost, mac.primaryPort)
                val rpcSession = MobileCoreRpcSession(transport)
                rpcSession.connect()
                session = rpcSession

                // Collect terminal.bytes events
                viewModelScope.launch(Dispatchers.IO) {
                    rpcSession.events.collect { envelope ->
                        if (envelope.topic == "terminal.bytes") {
                            val dataB64 = envelope.payload["data_b64"]?.jsonPrimitive?.content
                            if (dataB64 != null) {
                                val bytes = Base64.decode(dataB64, Base64.DEFAULT)
                                emulator.feed(bytes)
                            }
                        }
                    }
                }

                val accessToken = tokenStore.getAccessToken()

                // Subscribe to terminal.bytes event stream
                val streamId = UUID.randomUUID().toString()
                rpcSession.sendRequest(
                    method = "mobile.events.subscribe",
                    params = mapOf(
                        "stream_id" to JsonPrimitive(streamId),
                        "topics" to buildJsonArray { add("terminal.bytes") },
                    ),
                    authToken = accessToken,
                )

                // Request terminal replay and feed the snapshot into the emulator
                val replayResponse = rpcSession.sendRequest(
                    method = "mobile.terminal.replay",
                    params = mapOf(
                        "surface_id" to JsonPrimitive(surfaceId),
                        "workspace_id" to JsonPrimitive(workspaceId),
                    ),
                    authToken = accessToken,
                )
                val replayResult = replayResponse["result"]?.jsonObject
                val replayB64 = replayResult?.get("data_b64")?.jsonPrimitive?.content
                    ?: replayResult?.get("snapshot_data_b64")?.jsonPrimitive?.content
                if (replayB64 != null) {
                    val bytes = Base64.decode(replayB64, Base64.DEFAULT)
                    emulator.feed(bytes)
                }

                _state.value = TerminalUiState.Connected(displayLines())
            } catch (e: Exception) {
                _state.value = TerminalUiState.Error(e.message ?: "Connection failed")
            }
        }
    }

    /** Send keyboard input to the terminal. */
    fun sendInput(text: String) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val rpc = session ?: return@launch
                val encoded = Base64.encodeToString(text.toByteArray(), Base64.NO_WRAP)
                rpc.sendRequest(
                    method = "mobile.terminal.input",
                    params = mapOf(
                        "surface_id" to JsonPrimitive(surfaceId),
                        "workspace_id" to JsonPrimitive(workspaceId),
                        "data" to JsonPrimitive(encoded),
                    ),
                    authToken = tokenStore.getAccessToken(),
                )
            } catch (e: Exception) {
                // Input delivery failure is non-fatal
            }
        }
    }

    /** Feed raw bytes into the emulator. Used by tests to bypass the network. */
    fun feedBytesForTest(bytes: ByteArray) {
        emulator.feed(bytes)
    }

    override fun onCleared() {
        super.onCleared()
        session?.disconnect()
    }
}

